$employees=$conn->query("SELECT u.user_id,u.employee_id,COALESCE(NULLIF(u.full_name,''),CONCAT(u.first_name,' ',u.last_name)) name,u.position,u.employment_status,u.date_hired,u.role,u.department,u.status,u.email,u.phone FROM users u WHERE u.status='ACTIVE' AND u.is_active=1 AND $scope ORDER BY u.first_name,u.last_name")->fetch_all(MYSQLI_ASSOC);
$leaveYear=max(2000,min(2100,(int)($_GET['year']??date('Y'))));$leaveMonth=max(0,min(12,(int)($_GET['month']??0)));$leaveSummaries=[];$attendanceRecords=[];if(in_array($view,['attendance_leave','attendance_leave_encode'],true)){if($view==='attendance_leave'&&$leaveMonth>0){$leaveResult=$conn->query("SELECT employee_id,SUM(late_minutes>0) late_count,COALESCE(SUM(late_minutes),0) late_minutes_total,SUM(leave_type='ABSENT') absent_count,COALESCE(SUM(IF(leave_type='VACATION LEAVE',leave_days,0)),0) vacation_leave_used,COALESCE(SUM(IF(leave_type='SICK LEAVE',leave_days,0)),0) sick_leave_used,COALESCE(SUM(IF(leave_type='SPECIAL PRIVILEGE LEAVE',leave_days,0)),0) special_privilege_leave_used,COALESCE(SUM(IF(leave_type='WELLNESS LEAVE',leave_days,0)),0) wellness_leave_used,COALESCE(SUM(IF(leave_type='CALAMITY LEAVE',leave_days,0)),0) calamity_leave_used FROM nursing_employee_attendance WHERE YEAR(record_date)=$leaveYear AND MONTH(record_date)=$leaveMonth GROUP BY employee_id");}else{$leaveResult=$conn->query("SELECT * FROM nursing_employee_leave_summary WHERE record_year=$leaveYear");}foreach($leaveResult->fetch_all(MYSQLI_ASSOC)as$leaveRow)$leaveSummaries[(int)$leaveRow['employee_id']]=$leaveRow;if($view==='attendance_leave_encode'){$attendanceRecords=$conn->query("SELECT a.*,COALESCE(NULLIF(u.full_name,''),CONCAT(u.first_name,' ',u.last_name)) employee_name,u.department FROM nursing_employee_attendance a JOIN users u ON u.user_id=a.employee_id WHERE YEAR(a.record_date)=$leaveYear AND $scope ORDER BY a.record_date DESC,a.id DESC LIMIT 200")->fetch_all(MYSQLI_ASSOC);}}
$staffGroup=preg_replace('/[^a-z_]/','',(string)($_GET['staff_group']??''));
if($view==='employees'&&in_array($staffGroup,['nurse','nursing_attendant','midwife','clerk'],true)){
 $employees=array_values(array_filter($employees,static function(array $employee)use($staffGroup):bool{
  $position=strtolower(trim((string)($employee['position']?:str_replace('_',' ',$employee['role']??''))));
  return match($staffGroup){
   'nursing_attendant'=>str_contains($position,'nursing attendant'),
   'midwife'=>str_contains($position,'midwife'),
   'clerk'=>str_contains($position,'clerk'),
   'nurse'=>(str_contains($position,'nurse')||str_contains($position,'nursing'))&&!str_contains($position,'nursing attendant'),
  };
 }));
}
$requirements=$conn->query('SELECT * FROM nursing_document_requirements WHERE is_active=1 ORDER BY category,document_name')->fetch_all(MYSQLI_ASSOC);
$docWhere=$scope.' AND d.archived_at IS NULL';$filter=(string)($_GET['filter']??'');if($view==='expiring'||$filter==='expiring')$docWhere.=" AND d.document_status<>'SUPERSEDED' AND d.verification_status='VERIFIED' AND d.expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 60 DAY)";if($filter==='pending')$docWhere.=" AND d.verification_status='FOR VERIFICATION'";if($view==='expired'||$filter==='expired')$docWhere.=" AND d.document_status<>'SUPERSEDED' AND d.verification_status='VERIFIED' AND d.expiry_date<CURDATE()";
foreach(['department'=>'u.department','category'=>'d.category','status'=>'d.verification_status'] as$key=>$col)if(($_GET[$key]??'')!=='')$docWhere.=" AND $col='".$conn->real_escape_string((string)$_GET[$key])."'";
$search=trim((string)($_GET['q']??''));if($search!==''){$q=$conn->real_escape_string($search);$docWhere.=" AND (u.first_name LIKE '%$q%' OR u.last_name LIKE '%$q%' OR u.user_id LIKE '%$q%' OR d.document_type LIKE '%$q%')";}
$docs=$conn->query("SELECT d.*,COALESCE(NULLIF(u.full_name,''),CONCAT(u.first_name,' ',u.last_name)) employee_name,u.department,u.role,CONCAT(up.first_name,' ',up.last_name) uploader,CONCAT(v.first_name,' ',v.last_name) verifier FROM nursing_employee_documents d JOIN users u ON u.user_id=d.employee_id LEFT JOIN users up ON up.user_id=d.uploaded_by LEFT JOIN users v ON v.user_id=d.verified_by WHERE $docWhere ORDER BY d.created_at DESC")->fetch_all(MYSQLI_ASSOC);
$documentGroups=[];foreach($docs as$d){$employeeKey=(int)$d['employee_id'];if(!isset($documentGroups[$employeeKey]))$documentGroups[$employeeKey]=['employee_id'=>$employeeKey,'employee_name'=>$d['employee_name'],'department'=>$d['department'],'documents'=>[]];$documentGroups[$employeeKey]['documents'][]=$d;}
$pendingVerificationDocs=[];if($canVerify)$pendingVerificationDocs=$conn->query("SELECT d.*,COALESCE(NULLIF(u.full_name,''),CONCAT(u.first_name,' ',u.last_name)) employee_name,u.department FROM nursing_employee_documents d JOIN users u ON u.user_id=d.employee_id WHERE $scope AND d.archived_at IS NULL AND d.document_status<>'SUPERSEDED' AND d.verification_status='FOR VERIFICATION' ORDER BY d.created_at ASC")->fetch_all(MYSQLI_ASSOC);

// Generate deduplicated expiry notifications at the required milestones.
$conn->query("INSERT IGNORE INTO nursing_document_notifications(employee_document_id,employee_id,notification_type,message,notification_date) SELECT d.id,d.employee_id,CASE WHEN DATEDIFF(d.expiry_date,CURDATE())<0 THEN 'DOCUMENT EXPIRED' ELSE 'DOCUMENT EXPIRING SOON' END,CONCAT(d.document_type,' of ',u.first_name,' ',u.last_name,CASE WHEN DATEDIFF(d.expiry_date,CURDATE())<0 THEN ' has expired.' ELSE CONCAT(' will expire in ',DATEDIFF(d.expiry_date,CURDATE()),' days.') END),d.expiry_date FROM nursing_employee_documents d JOIN users u ON u.user_id=d.employee_id WHERE d.archived_at IS NULL AND d.document_status<>'SUPERSEDED' AND d.expiry_date IS NOT NULL AND (DATEDIFF(d.expiry_date,CURDATE())<0 OR DATEDIFF(d.expiry_date,CURDATE()) BETWEEN 0 AND 60)");
$notices=$conn->query("SELECT n.* FROM nursing_document_notifications n JOIN users u ON u.user_id=n.employee_id WHERE n.status='UNREAD' AND $scope ORDER BY n.created_at DESC LIMIT 25")->fetch_all(MYSQLI_ASSOC);
$compliance=[];
foreach($employees as$e){
 $employeePosition=str_replace('_',' ',(string)($e['position']?:$e['role']));
 $normalizedPosition=strtolower($employeePosition);
 $normalizedRole=strtolower(str_replace('_',' ',(string)$e['role']));
 $isNursingAttendant=str_contains($normalizedPosition,'nursing attendant');
 $isNurseOrMidwife=(str_contains($normalizedPosition,'nurse')||str_contains($normalizedPosition,'midwife'))&&!$isNursingAttendant;
 $isSecretary=str_contains($normalizedPosition,'secretary')||str_contains($normalizedRole,'secretary');
 $isClerk=str_contains($normalizedPosition,'clerk')||str_contains($normalizedRole,'clerk');
 $requiredDocumentNames=$isSecretary?['Diploma','Proof of Appointment','PDS','BLS']:($isClerk?['Diploma','Proof of Appointment','PDS']:($isNursingAttendant?['Diploma','Proof of Appointment','PDS','BLS']:($isNurseOrMidwife?['Diploma','Proof of Appointment','PDS','PRC License','BLS']:[])));
 $req=array_values(array_filter($requirements,fn($r)=>in_array($r['document_name'],$requiredDocumentNames,true)&&(!$r['department']||$r['department']===$e['department'])&&(!$r['employment_type']||strcasecmp((string)$r['employment_type'],(string)$e['employment_status'])===0)));
 if($isSecretary)$req[]=['document_name'=>'PRC License / Civil Service Eligibility'];
 $employeeDocs=array_values(array_filter($docs,fn($d)=>(int)$d['employee_id']===(int)$e['user_id']&&!in_array($d['document_status'],['SUPERSEDED','ARCHIVED'],true)));
 $complete=0;$missing=[];$requiredPending=0;$requiredRejected=0;$requiredExpired=0;$requiredExpiring=0;
 foreach($req as$r){
  $acceptedDocumentNames=$r['document_name']==='PRC License / Civil Service Eligibility'?['PRC License','Civil Service Eligibility']:[$r['document_name']];
  $matching=array_values(array_filter($employeeDocs,fn($d)=>in_array($d['document_type'],$acceptedDocumentNames,true)));
  if(!$matching){$missing[]=$r['document_name'];continue;}
  $found=$matching[0];$display=edDisplayStatus($found);
  if($found['verification_status']==='FOR VERIFICATION'){$requiredPending++;continue;}
  if(in_array($found['verification_status'],['REJECTED','UPDATE REQUESTED'],true)){$requiredRejected++;continue;}
  if($display==='EXPIRED'){$requiredExpired++;continue;}
  if($found['verification_status']==='VERIFIED'){$complete++;if($display==='EXPIRING SOON')$requiredExpiring++;}
 }
 $pending=count(array_filter($employeeDocs,fn($d)=>$d['verification_status']==='FOR VERIFICATION'));
 $expiring=count(array_filter($employeeDocs,fn($d)=>edDisplayStatus($d)==='EXPIRING SOON'));
 $expired=count(array_filter($employeeDocs,fn($d)=>edDisplayStatus($d)==='EXPIRED'));
 $total=count($req);$pct=$total?(int)round($complete/$total*100):0;
 $status=$total===0?'NOT REQUIRED':($requiredRejected||$requiredExpired||$missing?'INCOMPLETE':($requiredPending?'FOR VERIFICATION':($requiredExpiring?'EXPIRING SOON':($complete===$total?'COMPLETE':'INCOMPLETE'))));
 $compliance[$e['user_id']]=compact('total','complete','missing','expiring','expired','pending','pct','status');
}
$stats=['employees'=>count($employees),'complete'=>count(array_filter($compliance,fn($c)=>$c['status']==='COMPLETE')),'missing'=>count(array_filter($compliance,fn($c)=>count($c['missing'])>0)),'pending'=>count(array_filter($docs,fn($d)=>$d['verification_status']==='FOR VERIFICATION')),'expiring'=>count(array_filter($docs,fn($d)=>edDisplayStatus($d)==='EXPIRING SOON')),'expired'=>count(array_filter($docs,fn($d)=>edDisplayStatus($d)==='EXPIRED')),'recent'=>count(array_filter($docs,fn($d)=>$d['created_at']>=date('Y-m-d H:i:s',strtotime('-7 days'))))];
