roup['employee_id']?>" data-open-employee-docs="<?=$group['employee_id']?>"><i class="fa-solid fa-folder-open"></i> View &amp; Verify Documents</a></td></tr><?php endforeach;?><?php if(!$documentGroups):?><tr><td colspan="7" class="empty">No matching employee documents found.</td></tr><?php endif;?></tbody></table></div><?php foreach($documentGroups as$group):?><dialog class="modal employee-doc-modal" id="employeeDocs<?=$group['employee_id']?>" <?=$openEmployeeId===(int)$group['employee_id']?'open':''?>><div class="modal-head"><div><strong><?=h($group['employee_name'])?></strong><br><small><?=h(str_replace('_',' ',$group['department']??''))?> · <?=count($group['documents'])?> files</small></div><button type="button" class="close" onclick="this.closest('dialog').close()">×</button></div><div class="modal-body"><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Version</th><th>Issued</th><th>Expiration</th><th>Days</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($group['documents'] as$d):$days=$d['expiry_date']?(int)floor((strtotime($d['expiry_date'])-strtotime(date('Y-m-d')))/86400):null;$st=edDisplayStatus($d);?><tr><td><strong><?=h($d['document_type'])?></strong><br><small><?=h($d['original_name'])?></small></td><td>v<?=$d['version_no']?></td><td><?=edDate($d['issue_date'])?></td><td><?=edDate($d['expiry_date'])?></td><td><?=$days===null?'—':$days?></td><td><span class="badge <?=strtolower(str_replace(' ','-',$st))?>"><?=h($st)?></span><?php if($d['verification_remarks']):?><br><small><?=h($d['verification_remarks'])?></small><?php endif;?></td><td><div class="actions"><a class="btn light" target="_blank" href="?download=<?=$d['id']?>">View PDF</a><button type="button" class="btn light" onclick='openHistory(<?=json_encode($d,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Details</button><?php if($canVerify&&$d['verification_status']==='FOR VERIFICATION'):?><button type="button" class="btn green" onclick="openVerification(<?=$d['id']