/tbody></table></div></section><?php endforeach;?><section class="panel" id="history"><h2>Document History</h2><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Uploaded</th><th>Uploaded By</th><th>Verification</th><th>Effective</th><th>Expiration</th></tr></thead><tbody><?php foreach($pd as$d):?><tr><td><?=h($d['document_type'])?> <?=h($d['document_status']==='SUPERSEDED'?'(Old File)':'')?></td><td><?=h($d['created_at'])?></td><td><?=h($d['uploader']?:'—')?></td><td><?=h($d['verification_status'])?></td><td><?=edDate($d['issue_date'])?></td><td><?=edDate($d['expiry_date'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>

