</main></div><script>const documentTypes=<?=json_encode($types)?>,expiringDocumentTypes=<?=json_encode($expiringTypes)?>;function syncExpiry(){const t=document.querySelector('[data-type]'),f=document.querySelector('[data-expiry-field]');if(!t||!f)return;const required=expiringDocumentTypes.includes(t.value),input=f.querySelector('input');f.hidden=!required;input.required=required;if(!required)input.value=''}function syncTypes(){const c=document.querySelector('[data-category]'),t=document.querySelector('[data-type]');if(!c||!t)return;t.innerHTML=(documentTypes[c.value]||[]).map(x=>`<option>${x}</option>`).join('');syncExpiry()}function syncReplacementExpiry(){const t=document.getElementById('replaceType'),f=document.querySelector('[data-replace-expiry]');if(!t||!f)return;const required=expiringDocumentTypes.includes(t.value),input=f.querySelector('input');f.hidden=!required;input.required=required;if(!required)input.value=''}window.openEmployeeDocuments=function(id){const modal=document.getElementById('employeeDocs'+id);if(!modal){alert('Employee document list was not found.');return}if(typeof modal.showModal==='function'){try{modal.showModal();return}catch(error){}}modal.setAttribute('open','');modal.style.display='block';modal.style.position='fixed';modal.style.inset='5vh auto auto 50%';modal.style.transform='translateX(-50%)';modal.style.zIndex='9999'};function openVerification(id,action){const modal=document.getElementById('verificationModal'),idField=document.getElementById('verifyId'),actionField=document.getElementById('verifyAction'),frame=document.getElementById('reviewPdfFrame'),link=document.getElementById('reviewPdfLink'),decision=document.getElementById('reviewDecision'),label=document.getElementById('reviewDocumentLabel'),submit=document.getElementById('reviewSubmitButton');if(!modal||!idField||!actionField)return;const url='?download='+encodeURIComponent(id),isReject=action==='reject';idField.value=id;actionField.value=action;if(frame)frame.src=url;if(link)link.href=url;if(decision)decision.value=isReject?'REJECT':'VERIFY';if(label)label.textContent=(isReject?'Reject':'Verify')+' document #'+id+' after reviewing the PDF.';if(submit){submit.textContent=isReject?'Reject Document':'Verify Document';submit.className='btn '+(isReject?'red':'green')}const remarks=modal.querySelector('[name="verification_remarks"]');if(remarks){remarks.value='';remarks.required=isReject}modal.showModal()}function openReplacement(id,employee,category,type){const modal=document.getElementById('replaceModal');if(!modal)return;document.getElementById('replaceId').value=id;document.getElementById('replaceEmployee').value=employee;document.getElementById('replaceCategory').value=category;document.getElementById('replaceType').value=type;syncReplacementExpiry();modal.showModal()}document.querySelector('[data-category]')?.addEventListener('change',syncTypes);document.querySelector('[data-type]')?.addEventListener('change',syncExpiry);syncTypes();document.querySelectorAll('[data-search]').forEach(i=>i.addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('[data-search-body] [data-row]').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){if(typeof d.close==='function')d.close();else{d.removeAttribute('open');d.style.display='none'}}}));document.querySelector('[data-ed-open]')?.addEventListener('click',()=>document.body.classList.add('ed-sidebar-open'));document.querySelectorAll('[data-ed-close]').forEach(el=>el.addEventListener('click',()=>document.body.classList.remove('ed-sidebar-open')));function openHistory(d){alert(`${d.document_type}\nVersion: ${d.version_no}\nUploaded: ${d.created_at}\nVerification: ${d.verification_status}\nRemarks: ${d.verification_remarks||'None'}`)}</script></body></html>
